export const contractId = (number: StoryLessonNumber) => `conversational-skills-L7-C3-${number}-${contractEpisodes[number].skill}-en-v1`;

export function buildContractLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, contractEpisodes[number], previous, reference, {
    id: contractId(number), chapterName: 'Behind the Contract', pronunciation: contractPronunciation[number],
    setting: 'Spotlight Works and the fictional Apex Entertainment headquarters in Tokyo, with proposal meetings, legal reviews and a celebration dinner. The story follows Kai’s developing music partnership.',
    previousSummary: index === 0 ? algorithmEpisodes[9].closing : contractEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(7)}\nReference: Beyond the Spotlight, Chapter 3: Behind the Contract. Owner target is TOEIC 550-780, overriding the C1-C2 subtitle. Eight source episodes use slots 1-4 and 6-9; 5/10 remain dynamic checkpoints. English only, four Step A expressions, Step B-only pronunciation with exact bold stress, no Part III or extra pronunciation commentary. Tutor-first short dialogue, private listening, fresh reading missions, fixed English feedback. No new artwork or romance. Continue Maya, Natsumi, Jisoo, Luis, Kai and Mr. Shibata; introduce entertainment lawyer Ms. Hayashi. Monday offer follows the showcase and Chapter 2’s invitation to discuss. Recording facilities, international distribution and promotion are opportunities, not achieved international fame. Considerable producer input requires clarification. Next afternoon lawyer explains proposed control of covered masters for an extended period. Advance is paid upfront against future royalties, with specified recoupable costs recovered before additional recording royalties under these terms. No amounts, years, rates, all-cost claims, personal debt, concert income or songwriting royalty deduction is supplied. A composition and its particular recording have distinct rights; do not turn fictional explanation into universal legal advice. One week later producer suggests shorter songs, hooks and possible collaborators; Kai can keep writing, with commercial release aims. No recorded revision or settled approval rights yet. Financial scenarios are possibilities without supplied figures or guaranteed earnings; independence gives control with financial risk. Limited licensing, defined period and clearer creative approval begin as proposals. Team involvement is not guaranteed until later agreement; do not invent exact jobs or fees. Following week counterproposal requests two new singles, limited licensing, defined expenses, meaningful creative approval, plus Spotlight Works management and creative coordination. Mr. Shibata raises risk, Maya explains evaluation benefit. Two-hour meeting ends without final agreement. Several days later revised two-single partnership has defined recoupable expenses and a limited licensing period. Kai retains ownership of existing independent recordings; new release rights/approvals are outlined, but exact future master ownership or veto power is not specified. Natsumi and Ms. Hayashi review final documents; legal review completes before voluntary signing. Dinner fame joke is a joke. Apex then proposes immediate recording and a promotional tour across several major Japanese cities. No exact itinerary, acceptance, completed work or resolved preparation schedule. End with new workload pressure.`,
  });
  lesson.storyData.storyTitle = 'Beyond the Spotlight';
  lesson.storyData.characters = [
    { id: 'maya', name: 'Maya Kurose', role: 'main', description: 'Creative producer at Spotlight Works. She asks about artistic input, financial scenarios and preparation time.' },
    { id: 'natsumi', name: 'Natsumi Ito', role: 'supporting', description: 'Talent manager who requests full terms, negotiates continued involvement and reviews documents with the lawyer.' },
    { id: 'jisoo', name: 'Jisoo', role: 'supporting', description: 'Digital strategist who compares the offer with independence and welcomes the new opportunity.' },
    { id: 'luis', name: 'Luis', role: 'supporting', description: 'Videographer who asks about costs, recording rights and the existing team’s future role.' },
    { id: 'kai', name: 'Kai Nakamura', role: 'supporting', description: 'Singer-songwriter behind Paper Skyline. He balances growth, creative control and team relationships before signing the revised partnership.' },
    { id: 'shibata', name: 'Mr. Shibata', role: 'supporting', description: 'Apex Entertainment representative who presents the offer and responds to the counterproposal’s risks.' },
    { id: 'hayashi', name: 'Ms. Hayashi', role: 'supporting', description: 'Entertainment lawyer who explains the proposed recording and payment terms, negotiates revisions and reviews final documents.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 7, chapter: 3, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 3: Behind the Contract', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildContractChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildContractLesson(number, {}, reference));
}
